    <title>Midnight in Manhattan | A Cinematic SVG Experience</title>
    <style>
        :root {
            --sky-top: #020107;
            --sky-bottom: #201e33;
            --water: #050b1a;
            --accent-gold: #ffcc33;
            --window-light: rgba(255, 240, 150, 0.8);
        }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            overflow: hidden;
            background-color: var(--sky-top);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        .scene-container {
            position: relative;
            width: 100vw;
            height: 100vh;
            background: linear-gradient(to bottom, var(--sky-top) 0%, var(--sky-bottom) 70%, var(--water) 100%);
            display: flex;
            align-items: flex-end;
            justify-content: center}

        /* The SVG Canvas */
        svg {
            width: 100%;
            height: 85vh;
            display: block;
            filter: drop-shadow(0 0 20px rgba(0,0,0,0.5));
        }

        /* Animations */
        @keyframes flicker {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.3; }
            70% { opacity: 0.8; }
        }

        @keyframes float {
            0% { transform: translateY(0px); }
            50% { transform: translateY(-10px); }
            100% { transform: translateY(0px); }
        }

        @keyframes glow {
            0%, 100% { filter: blur(4px) brightness(1); }
            50% { filter: blur(8px) brightness(1.5); }
        }

        @keyframes shimmer {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
        }

        /* Classes for specific SVG elements */
        .window { fill: var(--window-light); animation: flicker 4s infinite ease-in-out; }
        .window-dim { fill: rgba(255, 255, 255, 0.1); }
        .star { fill: white; animation: flicker 3s infinite; }
        .moon { fill: #fffce0; filter: blur(2px); animation: glow 8s infinite ease-in-out; }
        .reflection { opacity: 0.3; transform: scaleY(-1); }
        .boat { animation: float 5s infinite ease-in-out; }
        .fog { fill: rgba(255,255,255,0.05); filter: blur(20px); }

        /* UI Overlay */
        .overlay {
            position: absolute;
            top: 40px;
            left: 40px;
            color: white;
            pointer-events: none;
            z-index: 10;
        }

        h1 {
            margin: 0;
            font-size: 2.5rem;
            letter-spacing: 8px;
            text-transform: uppercase;
            opacity: 0.8;
        }

        p {
            margin: 5px 0;
            font-weight: 300;
            letter-spacing: 2px;
            color: var(--accent-gold);
        }
    </xml>
    </style>
